INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blast Them All', 'Reload your weapon, the show''s about to start! Blast Them All is a wave-based twin stick shooter where you face endless hordes of hungry zombies. Use your agility, pick up weapons and activate traps to defend yourself, build up your strength, collect points and reach the top of the leaderboard!' FROM games WHERE igdb_id = 284020 ON CONFLICT (game_id, language_code) DO NOTHING;
