INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tokyo Coffee: Grinding in the Pandemic', 'Remembering the COVID-19 pandemic... It started in the year 2020. The events that unfolded in a cafe in Tokyo are now a nostalgic memory. Sit back, brew yourself a hot cup of coffee (or tea), and immerse yourself in the stories of the staff and different customers who visited the cafe.' FROM games WHERE igdb_id = 310311 ON CONFLICT (game_id, language_code) DO NOTHING;
