INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animeahikoaprinceaverse A4: Prince Akihiko & Princess A', 'When the prince of the kingdom was cursed, rendering his magic uncontrollable, However, the curse weakened when the prince was near his two fiancées. One of his fiancées managed to discover the origin of the curse, and they embarked on an adventure to lift the curse from the prince.' FROM games WHERE igdb_id = 303154 ON CONFLICT (game_id, language_code) DO NOTHING;
