INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crazy Shipping', 'Crazy Shipping is a free-to-play space trading and logistics management game. Players run a transportation company using ships piloted by cats, delivering cargo and passengers between stations across the solar system. The game features a risk-reward system where players balance legitimate deliveries against more profitable but risky "hot" cargo, while managing station alert levels and random events. Progress is made by expanding your fleet, purchasing stations, and upgrading facilities using currency earned through gameplay and optional in-game purchases.' FROM games WHERE igdb_id = 324080 ON CONFLICT (game_id, language_code) DO NOTHING;
