INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RP7: Spin Your Own Encounter', 'RP7 is a slot-managing roguelike. Instead of character control, you can roll seven random encounter slots to create your character''s journey. Roll and re-roll each step of your journey as you plan ahead. With one simple mechanic, you''ll experience infinite RPG gameplay. Fight monsters, gather golds, be more strong, and find your missing pet frog!' FROM games WHERE igdb_id = 135431 ON CONFLICT (game_id, language_code) DO NOTHING;
