INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Unknown 9: Awakening - Deluxe Edition', 'You are Haroona, a Quaestor born with the ability to venture into a mysterious dimension that overlaps our own, known only as the Fold. On her quest for powerful hidden knowledge, Haroona will learn to master her unique connection to the Fold, which allows her to channel its powers into our world... But such power does not go unnoticed and Haroona quickly becomes the target of a splinter faction calling themselves the Ascendants, who want to use the Fold to alter the course of human history.' FROM games WHERE igdb_id = 331832 ON CONFLICT (game_id, language_code) DO NOTHING;
