INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jesus Christ Simulator', '''Jesus Christ Simulator'' is a new take on the ''Superhero Simulator'' game genre. You are tasked by God your Father with fixing the broken system that humans now live in. Armed with Unlimited Miracles, Flight & Superpowers, you will change the world and help its people. You are THE Ultimate Superhero!' FROM games WHERE igdb_id = 303590 ON CONFLICT (game_id, language_code) DO NOTHING;
