INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'LEGO Super Mario Goal', 'LEGO Super Mario Goal, referred to simply as Lego Mario in the cable box menu and as Super Mario Lego Goal in the game''s description, is a game released in 2024 by Play.Works. It is a soccer game loosely based on the LEGO Super Mario toy line, featuring LEGO Mario and LEGO Luigi in the loading screen and LEGO Princess Peach in the winning and losing screens. The game''s promotional artwork is repurposed from New Super Mario Bros. U. It is an altered version of a game released in 2020 by the same developer named Pongoal.
