INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Urban Skater: Skateboard Delivery City Challenge', 'Welcome to Urban Skater - Skateboard Delivery City Challenge, an adrenaline-fueled adventure that puts you on wheels – or rather, a board – like never before! Strap on your helmet, grab your skateboard, and prepare to become the fastest (and coolest) food delivery person in town. Race against time, weave through bustling city streets, and deliver piping hot meals to hungry customers in this fast-paced and exhilarating experience.' FROM games WHERE igdb_id = 306752 ON CONFLICT (game_id, language_code) DO NOTHING;
