INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Button Game', 'The Button Game is a simple button clicker. Simple. You click the big button, and get the score as high as possible! Look out! The number does not hold on its own. The higher the score, the higher chance it has to decrease. If it reaches 0 after you initially leave it, you lose.' FROM games WHERE igdb_id = 370417 ON CONFLICT (game_id, language_code) DO NOTHING;
