INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dr. Bloodshot', 'Dr. Bloodshot is a short survival horror game. It''s set in an old mansion filled with monsters that the player has to avoid (either by running away or by hiding in cabinets). The objective is to reach the well secured laboratory of Dr. Bloodshot, which can be done by sabotaging various power stations across the mansion.' FROM games WHERE igdb_id = 311041 ON CONFLICT (game_id, language_code) DO NOTHING;
