INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Animal Crossing: Pocket Camp Complete', 'Animal Crossing: Pocket Camp Complete is the offline successor to Animal Crossing: Pocket Camp, developed to provide a full, standalone experience. This version retains the core gameplay features of designing your own campsite and talking to villagers, while offering an accessible way for players to experience the game after the original Pocket Camp''s End-of-Life.' FROM games WHERE igdb_id = 321011 ON CONFLICT (game_id, language_code) DO NOTHING;
