INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Squirmish: The Videogame of Brawling Beasties', 'Squirmish is a hilarious turn-based card-battling game for online PVP or solo play. Find your favorite creature cards and battle them against your opponent''s beastie brigade. Strange strategies and interactions of the wildly-varying cards create a unique, unpredictable and infinitely-playable game!' FROM games WHERE igdb_id = 291269 ON CONFLICT (game_id, language_code) DO NOTHING;
