INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Other Side Of Mist And Mountain', 'In 2005, a sophomore student named Igarashi Mahane took a private train to Soukyo City. She disappeared after alighting at a station named "Kisaragi". Five years later, her lover, Yokoyama Shizuno, began investigating the case and strange stories started to unfold one after another.' FROM games WHERE igdb_id = 278108 ON CONFLICT (game_id, language_code) DO NOTHING;
