INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Where is the Tutorial', 'Where is the Tutorial is a game where the biggest challenge is simply figuring out how to play. Dropped into a whimsical world with no instructions, no hints, and no mercy, you''re left to navigate a series of increasingly bizarre levels using only your wits and a growing sense of frustration.' FROM games WHERE igdb_id = 322722 ON CONFLICT (game_id, language_code) DO NOTHING;
