INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Evil Beneath', 'In this retro PS1/PSX style game. Play as a reporter (Rosa Salinas) investigating strange phenomenon regarding people mysteriously disappearing after visiting a particular mansion located deep inside a forest. During your investigation you will encounter horrifying creatures ready to tear you limb from limb and devour you alive. Traverse your way through these monstrous creatures and discover the terrifying truths about the mansion in the forest, while trying to make your escape before it''s to late.' FROM games WHERE igdb_id = 288957 ON CONFLICT (game_id, language_code) DO NOTHING;
