INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Endless Deaths', 'Endless Deaths is a thrilling top-down twin-stick shooter rogue-like where players battle through procedurally generated zombie-infested levels, continuously leveling up and upgrading their gear to survive. With unique characters, special abilities, and a diverse arsenal of weapons, each playthrough offers fresh and exhilarating challenges.' FROM games WHERE igdb_id = 331920 ON CONFLICT (game_id, language_code) DO NOTHING;
