INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Scotland Yard: Hunting Mister X', 'Find Mister X in Scotland Yard’s trickiest case yet! Mister X has gone underground somewhere in London, and the only clues are the tickets he carelessly threw away. But where did he use them? Look! There! Was that a quick glimpse of him?' FROM games WHERE igdb_id = 312078 ON CONFLICT (game_id, language_code) DO NOTHING;
