INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('meet-cute-muscle-rivals', 337684, '2024-12-19', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9lr5.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scw18r.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Meet Cute: Muscle Rivals', 'In a whimsical high-fantasy world, two rival elves, Lyssaria and Alen, find themselves locked in a fierce and hilariously petty battle of strength and wit. Both are obsessed with bodybuilding and will stop at nothing to prove they are the strongest elf. Their over-the-top competitions fuel a long-standing rivalry rooted in a laughably trivial incident from their youth. Along the way, they discover that their rivalry might mask a deeper connection, and perhaps, there’s more to their bond than just competition. This light-hearted romantic comedy blends high-stakes adventure with laugh-out-loud moments and a touch of heartwarming romance, as two stubborn elves learn that the greatest strength comes from unity.' FROM games WHERE igdb_id = 337684 ON CONFLICT (game_id, language_code) DO NOTHING;
