INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Games For The Table', 'Can''t choose what game to play? Well this game is the game for you!Games for the Table are games inside a game. So far, the game contains a handful of games: checkers, chess, a unique fusion of checkers and chess, and a version of the well-know game, Crazy Eights, in development currently.' FROM games WHERE igdb_id = 340292 ON CONFLICT (game_id, language_code) DO NOTHING;
