INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Raven Tea', 'Raven Tear is a stylized co-op adventure (4 players) in a small open world with horror elements. Evil has gripped the small town of "Raven Tear", you - brave hunters, must take your faithful dog and your excellent car, turn up the radio to go on a journey through the locations and drive them all back to the underworld. Grow vegetables, catch fish, earn money for equipment and arrange a safari for monsters!' FROM games WHERE igdb_id = 371563 ON CONFLICT (game_id, language_code) DO NOTHING;
