INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ChatBattlers', 'ChatBattlers is a Twitch Integration game releasing on Steam in September. Steamers have get an interactive 3D set of both Idle, and engaging game mods. Both Transparency support as well as a Stream-Safe LoFi sound track are included. Users can download the app in order to customize their slime with weapons, skins, costumes, and accessories to appear in other streams. Join streams to compete and wind Gems to purchase customization.' FROM games WHERE igdb_id = 316821 ON CONFLICT (game_id, language_code) DO NOTHING;
