INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gentleman''s Proposal', 'Can’t find the right groom? You''re headed for an arranged marriage with a rich old man! But suddenly, four irresistible suitors appear in your life... Could one of them be your way out? Set in the glamorous 19th-century English social scene, where romance and passion are never far away, you must navigate thrilling encounters as a strong, bold young woman. Can you find your ''perfect proposal'' before time runs out?' FROM games WHERE igdb_id = 357121 ON CONFLICT (game_id, language_code) DO NOTHING;
