INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Puzzles For Clef', 'Puzzles for Clef is a relaxing adventure game focused on the eponymous heroine. Following a letter from her sister, Cres, our bunny friend Clef journeys to the island of her ancestors, to undertake a treasure hunt.. The journey will take her across a land of beauty, magic, and mystery, as she explores each of the island’s regions, solves its countless puzzles, unearths long-forgotten secrets, and rediscovers her family’s legacy.' FROM games WHERE igdb_id = 190917 ON CONFLICT (game_id, language_code) DO NOTHING;
