INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', '5-fun go ni Igai na Ketsumatsu: Monochrome no Toshokan', 'The game features 100 game-original stories with unique graphics and sounds, described as sometimes fun, other times scary, and occasionally moving. Each story can be completed in five minutes and ends with an unexpected twist. The stories available to read are determined by speaking to the game’s two librarians—the angelic Whi and devilish Lack—allowing you to forge your own story depending on what kind of conversations you have.' FROM games WHERE igdb_id = 292032 ON CONFLICT (game_id, language_code) DO NOTHING;
