INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Snap Snap', 'SNAP SNAP is a first-person psychological horror game with an oppressive atmosphere and intense gameplay. Use your camera to escape the monster and solve some puzzles. Use the charge sparingly, as the battery may run out and while it is charging at the station... you are defenseless. The game has four endings. Will you be able to open them all? Beautiful graphics, oppressive atmosphere and high-quality sound will help you fully immerse yourself in the terrifying world of SNAP SNAP.' FROM games WHERE igdb_id = 313560 ON CONFLICT (game_id, language_code) DO NOTHING;
