INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'RoboKiden', 'RoboKiden is an innovative team-based action game where five players collaborate to control a single mecha in strategic battles. Integrating Web3 technology and blockchain, the game uses the $KIDEN token for in-game transactions and NFT trading. Players can earn and trade $KIDEN, enhancing gameplay with digital ownership and economic opportunities. Developed by The Breach Studios and powered by Elixir Games, RoboKiden offers a unique gaming experience with vibrant characters and dynamic battles.' FROM games WHERE igdb_id = 306213 ON CONFLICT (game_id, language_code) DO NOTHING;
