INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Crayon Legend', 'Cursed nobles turned into Magic Doors watch their possessions eaten by an insatiable Mimic. Transported to this time-locked island, you must Jump, Lift, Search, and Feed to restore the kingdom. A family-friendly, 3D platformer with hand-coded physics, Unlock the doors to find your way home.' FROM games WHERE igdb_id = 348542 ON CONFLICT (game_id, language_code) DO NOTHING;
