INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Floor 9', 'In Floor 9, you find yourself trapped in a mysterious hotel known as "Hotel Liminal." To escape, you must identify anomalies on each floor. These anomalies can be anywhere - on the ground, in paintings, or even right in front of your eyes. You must check every corner carefully, as one mistake will send you back to the beginning, to Floor 9. The game offers you a unique blend of eerie atmosphere, puzzle-solving, and survival, all wrapped up in a psychologically thrilling experience.' FROM games WHERE igdb_id = 316478 ON CONFLICT (game_id, language_code) DO NOTHING;
