INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wolf Sheep & Cabbage', 'Wolf, Sheep, and Cabbage is a classic logic puzzle game. The goal is to help a farmer safely move a wolf, a sheep, and a cabbage across a river using a small boat. The boat can carry only one item at a time, and the farmer must be present for any crossing. The challenge is to make sure the wolf is never left alone with the sheep, and the sheep is never left alone with the cabbage.' FROM games WHERE igdb_id = 381383 ON CONFLICT (game_id, language_code) DO NOTHING;
