INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('blade-and-sorcery-nomad', 196375, '2024-10-28', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8zqz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar1k5b.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blade & Sorcery: Nomad', 'The era of the VR weightless, wiggle-sword combat is over. Blade & Sorcery: Nomad is a medieval fantasy sandbox like no other, focusing on melee, ranged and magic combat that fully utilizes a unique and realistic physics driven interaction and combat system. Built exclusively for VR, collisions are dictated by fine hitboxes, objects have weight and follow the laws of physics, creatures have full body physics and presence, and blades can be used to penetrate soft materials or deflect magic. In Blade & Sorcery: Nomad, the combat is limited only by your own creativity. Choose your weapon, choose your stance, choose your fighting style; Be the powerful warrior, ranger or sorcerer you always dreamed of becoming!' FROM games WHERE igdb_id = 196375 ON CONFLICT (game_id, language_code) DO NOTHING;
