INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('senpai-and-the-mysterious-island', 325686, '2024-12-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co95kn.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar40ol.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Senpai and the Mysterious Island', 'An RPG where you get to uncover the secrets of a mysterious island inhabited by succubi that was rumored to contain a lost ancient technology. Play as either the warrior Hula Elstia, or Sonia Lanternlily to a variety of combat styles, and dress them up with various outfits.' FROM games WHERE igdb_id = 325686 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 325686 AND ge.slug = 'role-playing-rpg' ON CONFLICT DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 325686 AND ge.slug = 'adventure' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 325686 AND c.slug = 'saikey-studios' ON CONFLICT DO NOTHING;
INSERT INTO game_companies (game_id, company_id, role, is_primary) SELECT g.id, c.id, 'developer', false FROM games g, companies c WHERE g.igdb_id = 325686 AND c.slug = 'ruhut-soft' ON CONFLICT DO NOTHING;